"""新增 OrderSequence 计数器表 + 从存量订单回填各业务日已用序号。

★ 回填策略（本迁移最关键的部分，理由见 backfill_order_sequence docstring）：
  按业务日逐日取 **max(已用序号)**，不是 count()。绝不能留初值 0。
"""
import re
from datetime import datetime

from django.db import migrations, models

# 只匹配序号版单号 ORD-YYYYMMDD-NNN。
# uuid 版 PO 单是 ORD-{8位HEX}（无第二个 '-'），天然不匹配 ⇒ 不会被计入。
# 注：即使HEX 恰好全是数字（概率约 2.3%），也因缺少第二个 '-' 而被排除。
_SEQ_ORDER_NO_RE = re.compile(r'^ORD-(\d{8})-(\d{3,})$')


def backfill_order_sequence(apps, schema_editor):
    """把存量序号版订单回填进 OrderSequence，逐业务日取 max。

    ★ 为什么必须取 max 而不是 count：
      生产 2026-07-17 已有 004-007 跳号（uuid 版 PO 单污染了旧 count()）。
      若按 count() 回填得4，下一单会取 005 —— 虽不撞已有单号，但计数口径依旧错乱；
      更糟的是若某日 count() > max（删除场景），会直接撞已存在单号。
      max() 是唯一保证"新号 > 所有历史号"的口径。

    ★ 幂等：可重复执行，只增不减（已存在行且 last_number 更大时跳过）。
    ★ 反向：清空 OrderSequence（表本身由 CreateModel 反向自动删除）。
    """
    Order = apps.get_model('transactions', 'Order')
    OrderSequence = apps.get_model('transactions', 'OrderSequence')

    per_day_max = {}
    for order_no in Order.objects.values_list('order_no', flat=True):
        m = _SEQ_ORDER_NO_RE.match(order_no or '')
        if not m:
            continue
        try:
            day = datetime.strptime(m.group(1), '%Y%m%d').date()
        except ValueError:
            continue
        seq = int(m.group(2))
        if seq > per_day_max.get(day, 0):
            per_day_max[day] = seq

    for day, last_number in per_day_max.items():
        row, created = OrderSequence.objects.get_or_create(
            biz_date=day, defaults={'last_number': last_number},
        )
        if not created and row.last_number < last_number:
            # 只增不减：重跑时不得让计数器回退（否则会撞已存在单号）
            row.last_number = last_number
            row.save(update_fields=['last_number'])


def clear_order_sequence(apps, schema_editor):
    """反向迁移：清空回填数据（表随后由 CreateModel 的反向操作删除）。"""
    OrderSequence = apps.get_model('transactions', 'OrderSequence')
    OrderSequence.objects.all().delete()


